function quickSort(a) {
  if (a.length <= 1) {
    return a;
  }
  var pivot = a[0];
  var rest = a.slice(1);
  var smaller = rest.filter(function (x) {
    return x < pivot;
  });
  var larger = rest.filter(function (x) {
    return x >= pivot;
  });
  return quickSort(smaller).concat([pivot], quickSort(larger));
}

console.log(quickSort([3, 1, 3, 2, 3]));
